package dev.jason.gboardpatches.extension.settings.search;

import android.content.Context;
import android.util.Log;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import dev.jason.gboardpatches.extension.settings.GboardPatchesSettingsContract;

/**
 * The settings search index packaged with the APK. {@link GboardSettingsSearchIndexData} is
 * generated by {@code GboardSettingsSearchIndexSnapshotTest}, which walks the feature tree and
 * records string resources, so searching never builds a settings screen.
 */
public final class GboardSettingsSearchIndex {
    private static final String TAG = "GboardPatches";
    private static final char OCCURRENCE_SEPARATOR = '@';

    private GboardSettingsSearchIndex() {
    }

    public static final class Entry {
        private final String[] path;
        private final int titleRes;
        private final int summaryRes;
        private final boolean page;

        Entry(String[] path, int titleRes, int summaryRes, boolean page) {
            this.path = path;
            this.titleRes = titleRes;
            this.summaryRes = summaryRes;
            this.page = page;
        }

        public String[] getPath() {
            return path.clone();
        }

        public int getTitleRes() {
            return titleRes;
        }

        /** 0 when the row has no fixed summary. */
        public int getSummaryRes() {
            return summaryRes;
        }

        /** Whether the entry names the page itself rather than a row on it. */
        public boolean isPage() {
            return page;
        }
    }

    public static List<Entry> entries() {
        List<Entry> entries = new ArrayList<Entry>(GboardSettingsSearchIndexData.ENTRIES.length);
        for (int[] entry : GboardSettingsSearchIndexData.ENTRIES) {
            entries.add(new Entry(
                    GboardSettingsSearchIndexData.PATHS[entry[0]],
                    entry[1],
                    entry[2],
                    entry[3] != 0));
        }
        return Collections.unmodifiableList(entries);
    }

    /**
     * Names the feature at {@code index} among its siblings: its class, plus how many earlier
     * siblings share that class, since one class can back several pages (flag patch pages).
     */
    public static String pathElement(List<? extends GboardPatchesSettingsContract.Feature> siblings,
            int index) {
        String className = siblings.get(index).getClass().getName();
        int occurrence = 0;
        for (int sibling = 0; sibling < index; sibling++) {
            GboardPatchesSettingsContract.Feature feature = siblings.get(sibling);
            if (feature != null && className.equals(feature.getClass().getName())) {
                occurrence++;
            }
        }
        return occurrence == 0 ? className : className + OCCURRENCE_SEPARATOR + occurrence;
    }

    /**
     * Resolves index paths to the available features they lead through, evaluating each feature's
     * availability once. Paths through an unavailable or missing feature are absent from the map.
     */
    public static final class PathResolver {
        private final Context context;
        private final List<GboardPatchesSettingsContract.Feature> roots;
        private final Map<String, List<GboardPatchesSettingsContract.Feature>> resolved =
                new HashMap<String, List<GboardPatchesSettingsContract.Feature>>();
        private final Map<GboardPatchesSettingsContract.Feature, Boolean> availability =
                new HashMap<GboardPatchesSettingsContract.Feature, Boolean>();

        public PathResolver(Context context,
                List<GboardPatchesSettingsContract.Feature> roots) {
            this.context = context;
            this.roots = roots == null
                    ? Collections.<GboardPatchesSettingsContract.Feature>emptyList()
                    : roots;
        }

        /** The features along {@code path}, or null when it no longer leads to an open page. */
        public List<GboardPatchesSettingsContract.Feature> resolve(String[] path) {
            String key = String.join(">", path);
            if (resolved.containsKey(key)) {
                return resolved.get(key);
            }
            List<GboardPatchesSettingsContract.Feature> features = resolveUncached(path);
            resolved.put(key, features);
            return features;
        }

        private List<GboardPatchesSettingsContract.Feature> resolveUncached(String[] path) {
            if (path.length == 0) {
                return null;
            }
            List<GboardPatchesSettingsContract.Feature> features =
                    new ArrayList<GboardPatchesSettingsContract.Feature>(path.length);
            List<GboardPatchesSettingsContract.Feature> candidates = roots;
            for (String element : path) {
                GboardPatchesSettingsContract.Feature match = find(candidates, element);
                if (match == null || !isAvailable(match)) {
                    return null;
                }
                features.add(match);
                try {
                    candidates = match.getNavigationChildren();
                } catch (Throwable throwable) {
                    Log.w(TAG, "Failed to list settings search children", throwable);
                    return null;
                }
            }
            return Collections.unmodifiableList(features);
        }

        private static GboardPatchesSettingsContract.Feature find(
                List<GboardPatchesSettingsContract.Feature> candidates, String element) {
            if (candidates == null) {
                return null;
            }
            for (int index = 0; index < candidates.size(); index++) {
                if (candidates.get(index) != null
                        && element.equals(pathElement(candidates, index))) {
                    return candidates.get(index);
                }
            }
            return null;
        }

        private boolean isAvailable(GboardPatchesSettingsContract.Feature feature) {
            Boolean cached = availability.get(feature);
            if (cached != null) {
                return cached;
            }
            boolean available;
            try {
                available = feature.isAvailable(context);
            } catch (Throwable throwable) {
                Log.w(TAG, "Failed to evaluate settings search availability", throwable);
                available = false;
            }
            availability.put(feature, available);
            return available;
        }
    }
}
